//! navidrome tool surface.
//!
//! Endpoint registry: `navidrome.{list, detail, create, update, delete}` —
//! generated by `#[endpoint_resource]`.
//!
//! Domain tools, all over Navidrome's Subsonic API:
//!   - `navidrome.server_info`         identity + protocol version
//!   - `navidrome.libraries`           configured music folders
//!   - `navidrome.library.scan`        trigger a rescan (incremental/full)
//!   - `navidrome.library.scan_status` poll an in-progress scan
//!   - `navidrome.now_playing`         who/what is currently streaming

use plugin_toolkit::prelude::*;

use crate::api::{MusicFolder, Navidrome, NowPlayingEntry, ScanStatus, ServerInfo};

use plugin_toolkit::media::{MediaBackend, MediaCapability, MediaError, MediaItem, MediaType};

#[endpoint_resource(plugin = "navidrome")]
pub struct NavidromeEndpoint {
    pub name: String,
    pub username: String,
    /// Sent as the Subsonic `p` query param (plaintext, over the connection
    /// the endpoint's route resolves to).
    #[secret]
    pub password: String,
    /// Skip TLS verification (self-signed certs).
    pub insecure: bool,
    pub enabled: bool,
}

pub async fn connect(name: &str) -> Result<Navidrome> {
    let password = plugin_toolkit::secrets::resolve_scoped("navidrome", name, "password")?;
    let row = endpoint_db::require(name)?;
    if !row.enabled {
        bail!("navidrome endpoint '{name}' is disabled");
    }
    let base_url = route::resolve_reachable(name, &row.routes, row.insecure).await?;
    Navidrome::new(
        &base_url,
        &row.username,
        password.expose_secret(),
        row.insecure,
    )
}

#[orca_struct(args)]
pub struct EndpointArgs {
    /// Registered navidrome endpoint name.
    #[arg(long)]
    pub name: String,
}

/// Server identity and Subsonic protocol version (`ping.view`).
#[orca_tool(domain = "navidrome", verb = "server_info", role = "read")]
async fn navidrome_server_info(args: EndpointArgs, _ctx: &ToolCtx) -> Result<ServerInfo> {
    connect(&args.name).await?.server_info().await
}

/// Configured music folders (`getMusicFolders.view`).
#[orca_tool(domain = "navidrome", verb = "libraries", role = "read")]
async fn navidrome_libraries(args: EndpointArgs, _ctx: &ToolCtx) -> Result<Vec<MusicFolder>> {
    connect(&args.name).await?.music_folders().await
}

#[orca_struct(args)]
pub struct ScanArgs {
    /// Registered navidrome endpoint name.
    #[arg(long)]
    pub name: String,
    /// Reprocess every file instead of only changed ones.
    #[arg(long)]
    #[serde(default)]
    pub full: bool,
}

/// Trigger a library rescan (`startScan.view`). Navidrome queues the scan and
/// returns at once; poll `navidrome.library.scan_status` for progress.
#[orca_tool(
    domain = "navidrome",
    verb = "library.scan",
    role = "admin",
    execute_gated = true
)]
async fn navidrome_library_scan(args: ScanArgs, _ctx: &ToolCtx) -> Result<ScanStatus> {
    connect(&args.name).await?.start_scan(args.full).await
}

/// Progress of an in-progress (or most recent) scan (`getScanStatus.view`).
#[orca_tool(domain = "navidrome", verb = "library.scan_status", role = "read")]
async fn navidrome_library_scan_status(args: EndpointArgs, _ctx: &ToolCtx) -> Result<ScanStatus> {
    connect(&args.name).await?.scan_status().await
}

/// Who/what is currently streaming (`getNowPlaying.view`).
#[orca_tool(domain = "navidrome", verb = "now_playing", role = "read")]
async fn navidrome_now_playing(args: EndpointArgs, _ctx: &ToolCtx) -> Result<Vec<NowPlayingEntry>> {
    connect(&args.name).await?.now_playing().await
}

/// `media` domain registration: navidrome serves (`ServedBy`) the `Music`
/// type. Resolves the same connection as the `navidrome.*` tools above —
/// the first enabled endpoint, since the trait carries no instance param.
#[derive(Debug, Clone, Default)]
pub struct NavidromeMedia;

impl NavidromeMedia {
    pub fn new() -> Self {
        Self
    }

    async fn connect(&self) -> std::result::Result<Navidrome, MediaError> {
        let rows = endpoint_db::list()
            .map_err(|e| MediaError::Transport(format!("read endpoints: {e}")))?;
        let ep = rows
            .into_iter()
            .filter(|r| r.enabled)
            .min_by(|a, b| a.name.cmp(&b.name))
            .ok_or_else(|| MediaError::NotFound("no enabled navidrome endpoint".into()))?;
        connect(&ep.name)
            .await
            .map_err(|e| MediaError::Transport(format!("{e:#}")))
    }
}

#[plugin_toolkit::orca_async]
impl MediaBackend for NavidromeMedia {
    fn name(&self) -> &str {
        "navidrome"
    }
    fn media_type(&self) -> MediaType {
        MediaType::Music
    }
    fn capabilities(&self) -> Vec<MediaCapability> {
        vec![MediaCapability::ServedBy]
    }
    fn endpoint(&self) -> String {
        String::new()
    }

    async fn list(&self) -> std::result::Result<Vec<MediaItem>, MediaError> {
        list_items(&self.connect().await?).await
    }

    async fn search(&self, query: &str) -> std::result::Result<Vec<MediaItem>, MediaError> {
        search_items(&self.connect().await?, query).await
    }
}

/// Enumerate the library as `MediaItem`s (`getArtists.view`). Split from
/// [`NavidromeMedia::list`] so the mapping is testable against a bare
/// [`Navidrome`] client, without exercising endpoint resolution.
async fn list_items(nav: &Navidrome) -> std::result::Result<Vec<MediaItem>, MediaError> {
    let artists = nav
        .artists()
        .await
        .map_err(|e| MediaError::Transport(format!("{e:#}")))?;
    Ok(artists
        .into_iter()
        .map(|a| MediaItem {
            id: a.id,
            title: a.name,
            status: None,
            path: None,
        })
        .collect())
}

/// Free-text search mapped to `MediaItem`s (`search3.view`), artists then
/// albums then songs.
async fn search_items(
    nav: &Navidrome,
    query: &str,
) -> std::result::Result<Vec<MediaItem>, MediaError> {
    let r = nav
        .search(query)
        .await
        .map_err(|e| MediaError::Transport(format!("{e:#}")))?;
    let mut out = Vec::with_capacity(r.artists.len() + r.albums.len() + r.songs.len());
    out.extend(r.artists.into_iter().map(|a| MediaItem {
        id: a.id,
        title: a.name,
        status: None,
        path: None,
    }));
    out.extend(r.albums.into_iter().map(|a| MediaItem {
        id: a.id,
        title: a.name,
        status: None,
        path: None,
    }));
    out.extend(r.songs.into_iter().map(|s| MediaItem {
        id: s.id,
        title: s.title,
        status: None,
        path: None,
    }));
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tools_declare_roles_and_gating() {
        let role = |n| plugin_toolkit::dispatch::required_role(n);
        for n in [
            "navidrome.server_info",
            "navidrome.libraries",
            "navidrome.library.scan_status",
            "navidrome.now_playing",
        ] {
            assert_eq!(role(n), Some("read"), "{n}");
        }
        assert_eq!(role("navidrome.library.scan"), Some("admin"));
        assert!(plugin_toolkit::dispatch::execute_gated_names().contains(&"navidrome.library.scan"));
    }

    #[test]
    fn connect_fails_when_the_password_secret_is_missing() {
        use std::sync::{Arc, Mutex};
        let caps = Arc::new(Mutex::new(Vec::new()));
        let log = caps.clone();
        let e = plugin_toolkit::capsink::with_cap_sink(
            Box::new(move |cap: &str, _: &str| {
                log.lock().unwrap().push(cap.to_string());
                match cap {
                    "secret.op" => Ok(json!({"value": null}).to_string()),
                    _ => Err(format!("unexpected {cap}")),
                }
            }),
            || {
                tokio::runtime::Builder::new_current_thread()
                    .build()
                    .unwrap()
                    .block_on(connect("nav"))
                    .err()
                    .unwrap()
            },
        );
        assert!(format!("{e:#}").contains("navidrome"), "{e:#}");
    }

    #[test]
    fn media_facet_advertises_served_by_and_music() {
        let m = NavidromeMedia::new();
        assert_eq!(m.name(), "navidrome");
        assert_eq!(m.media_type(), MediaType::Music);
        assert_eq!(m.capabilities(), vec![MediaCapability::ServedBy]);
    }

    use plugin_toolkit::serde_json::{self, Value};
    use std::sync::{Arc, Mutex};

    type Call = (String, String);

    fn serve<F>(path: &'static str, body: Value, f: F) -> Vec<Call>
    where
        F: FnOnce(),
    {
        let seen = Arc::new(Mutex::new(Vec::new()));
        let log = seen.clone();
        plugin_toolkit::capsink::with_cap_sink(
            Box::new(move |cap: &str, req: &str| {
                assert_eq!(cap, "http.request");
                let req: Value = serde_json::from_str(req).unwrap();
                let url = req["url"].as_str().unwrap().to_string();
                let method = req["method"].as_str().unwrap().to_string();
                let p = url.trim_start_matches("http://nav.test").to_string();
                log.lock().unwrap().push((method.clone(), p.clone()));
                let (status, resp) = if p.starts_with(path) {
                    (200, body.to_string())
                } else {
                    (404, "Not Found".to_string())
                };
                Ok(json!({"status": status, "headers": [], "body": resp.into_bytes()}).to_string())
            }),
            f,
        );
        let out = seen.lock().unwrap().clone();
        out
    }

    fn block<T>(f: impl std::future::Future<Output = T>) -> T {
        tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap()
            .block_on(f)
    }

    fn nav() -> Navidrome {
        Navidrome::new("http://nav.test/", "admin", "s3cret", false).unwrap()
    }

    #[test]
    fn list_items_maps_artists_to_media_items() {
        let mut got = Vec::new();
        serve(
            "/rest/getArtists.view",
            json!({"subsonic-response": {"status": "ok", "version": "1.16.1",
                "artists": {"index": [
                    {"name": "B", "artist": [{"id": "ar_1", "name": "Burial"}]}
                ]}
            }}),
            || got = block(list_items(&nav())).unwrap(),
        );
        assert_eq!(
            got,
            vec![MediaItem {
                id: "ar_1".into(),
                title: "Burial".into(),
                status: None,
                path: None,
            }]
        );
    }

    #[test]
    fn search_items_orders_artists_then_albums_then_songs() {
        serve(
            "/rest/search3.view",
            json!({"subsonic-response": {"status": "ok", "version": "1.16.1",
                "searchResult3": {
                    "artist": [{"id": "ar_1", "name": "Burial"}],
                    "album": [{"id": "al_1", "name": "Untrue"}],
                    "song": [{"id": "tr_1", "title": "Archangel"}]
                }
            }}),
            || {
                let items = block(search_items(&nav(), "burial")).unwrap();
                assert_eq!(
                    items,
                    vec![
                        MediaItem {
                            id: "ar_1".into(),
                            title: "Burial".into(),
                            status: None,
                            path: None,
                        },
                        MediaItem {
                            id: "al_1".into(),
                            title: "Untrue".into(),
                            status: None,
                            path: None,
                        },
                        MediaItem {
                            id: "tr_1".into(),
                            title: "Archangel".into(),
                            status: None,
                            path: None,
                        },
                    ]
                );
            },
        );
    }
}
